interface Describable {
    fn describe(self) -> String
}
record User { name: String }
impl Describable for User {
    fn describe(self) -> String {
        "a user"
    }
}
fn show<T>(x: T) -> String where T: Describable {
    x.describe()
}
pub type AppError = Failed(String)
pub fn main() -> Result<(), AppError> {
    let u = User { name: "a" }
    let text = show(u)
    return Ok(())
}

